using GraphApi.Models.FNZ.DocumentosTransaccion;namespace GraphApi.Services.FNZ.DocumentosTransaccion{    /// <summary>    /// Define las operaciones de negocio y persistencia para DocumentosTransaccions.    /// </summary>    public interface IDocumentosTransaccionService    {        /// <summary>        /// Obtiene la lista de DocumentosTransaccions con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadDocumentosTransaccion>> GetDocumentosTransaccions(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de DocumentosTransaccions con filtros opcionales.        /// </summary>        /// <param name="documentoTransaccionID">Filtro opcional para DocumentoTransaccionID.</param>        /// <param name="transaccionID">Filtro opcional para TransaccionID.</param>        /// <param name="documentoID">Filtro opcional para DocumentoID.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetDocumentosTransaccionsDynamic(            int? documentoTransaccionID,            int? transaccionID,            int? documentoID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo DocumentosTransaccion.        /// </summary>        /// <param name="objInput">Datos para crear el DocumentosTransaccion.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadDocumentosTransaccion> CreateDocumentosTransaccion(            clCreateDocumentosTransaccion objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un DocumentosTransaccion.        /// </summary>        /// <param name="objInput">Datos para actualizar el DocumentosTransaccion, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadDocumentosTransaccion?> UpdateDocumentosTransaccion(            clUpdateDocumentosTransaccion objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un DocumentosTransaccion por su ID.        /// </summary>        /// <param name="nDocumentosTransaccionID">ID del DocumentosTransaccion a eliminar.</param>        Task<bool> DeleteDocumentosTransaccion(int nDocumentosTransaccionID);    }}